// Compiles every fixture in spec/lib/fixtures/compiler and compares the
// result with the expected output in <name>.js (regenerate them with
// `node tasks/compiler/update_fixtures.mjs` and review the diff). Most of
// them were generated by the Ruby compiler, which the JS compiler matched.
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import vm from "node:vm";
import { Compiler } from "../../../lib/opal/compiler/index.mjs";
import { decodeSource } from "../../../lib/opal/compiler/builder/path_reader.mjs";

const FIXTURES = join(fileURLToPath(new URL(".", import.meta.url)), "..", "fixtures", "compiler");

function walk(dir, out = []) {
  for (const entry of readdirSync(dir).sort()) {
    const path = join(dir, entry);
    if (statSync(path).isDirectory()) walk(path, out);
    else if (path.endsWith(".rb")) out.push(path);
  }
  return out;
}

function fixtureOptions(source) {
  const m = /^# opal-options: (\{.*\})\s*$/.exec(source.split("\n")[0]);
  return m ? JSON.parse(m[1]) : {};
}

// The fixtures are matched as text, so nothing else shows that the generated
// code is JavaScript. Parsing them catches a splice that makes the output
// invalid, like an operator expression in front of `.valueOf()`.
function parseExpected(path, esm) {
  if (esm) {
    // vm.Script reads scripts only; node's own parser reads both, and it is
    // the parser a runner would use.
    execFileSync(process.execPath, ["--check", path], { stdio: "pipe" });
  } else {
    new vm.Script(readFileSync(path, "utf8"), { filename: path });
  }
}

for (const file of walk(FIXTURES)) {
  const name = relative(FIXTURES, file);
  const expectedPath = file.replace(/\.rb$/, ".js");

  test(name, () => {
    const source = decodeSource(readFileSync(file)); // honours encoding magic comments
    const expected = readFileSync(expectedPath, "utf8");
    const options = { file: name, warning: () => {}, ...fixtureOptions(source) };

    if (expected.startsWith("// error:")) {
      assert.throws(() => new Compiler(source, options).compile());
    } else {
      assert.equal(new Compiler(source, options).compile(), expected);
      parseExpected(expectedPath, Boolean(options.esm));
    }
  });
}
